command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/release-source-identity-20261006"
$expectedWork="911940b18120077c05759d8d4b9be90e1d6f3f86"
$expectedMain="8b3ff0da418f8d9c154f0984921359f4a620b552"
$source="bc63c8b48e466d1275cc6dcffb0c50e02d39db60"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "cleanup fetch failed"}
$mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
$workRef="refs/remotes/origin/"+$branch
$workSha=(& git rev-parse $workRef).Trim()
if($mainSha -ne $expectedMain){throw "main moved before cleanup: $mainSha"}
if($workSha -ne $expectedWork){throw "work branch moved before cleanup: $workSha"}

& git merge-base --is-ancestor $source refs/remotes/origin/main
if($LASTEXITCODE -ne 0){throw "binary source revision is not preserved in main history"}

$mainTree=(& git rev-parse "refs/remotes/origin/main^{tree}").Trim()
$workTree=(& git rev-parse ($workRef+"^{tree}")).Trim()
if($mainTree -ne $workTree){throw "refuse cleanup: merged main tree differs from work branch tree"}

& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "failed to delete merged release-source work branch"}
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "post-delete fetch failed"}
if(& git show-ref --verify --quiet $workRef){throw "release-source work branch still exists"}
Write-Host "RELEASE_SOURCE_WORK_BRANCH_CLEANUP=PASS"
